 "1. Liste fotografieren. 2. Angaben prüfen und Zeilen ankreuzen. 3. Mit „Tank anlegen“ bestätigen. Danach stehen die Tanks unter „Deine Tanks“, die Liste unter „Behälterlisten ansehen“.": {
  "en": "1. Take a photo of the list. 2. Check information and tick lines. 3. Confirm with “Create tank”. The tanks are then under “Your Tanks” and the list is under “View Container Lists”.",
  "fr": "1. Prenez une photo de la liste. 2. Vérifiez les informations et cochez les lignes. 3. Confirmez avec « Créer un réservoir ». Les réservoirs se trouvent alors sous « Vos réservoirs » et la liste se trouve sous « Afficher les listes de conteneurs ».",
  "es": "1. Tome una foto de la lista. 2. Consulta información y marca líneas. 3. Confirme con \"Crear tanque\". Los tanques se encuentran luego en \"Sus tanques\" y la lista en \"Ver listas de contenedores\".",
  "pt": "1. Tire uma foto da lista. 2. Verifique as informações e marque as linhas. 3. Confirme com “Criar tanque”. Os tanques estão então em “Seus Tanques” e a lista está em “Ver Listas de Contêineres”.",
  "el": "1. Τραβήξτε μια φωτογραφία της λίστας. 2. Ελέγξτε τις πληροφορίες και σημειώστε τις γραμμές. 3. Επιβεβαιώστε με «Δημιουργία δεξαμενής». Στη συνέχεια, οι δεξαμενές βρίσκονται στην ενότητα \"Οι δεξαμενές σας\" και η λίστα βρίσκεται στην ενότητα \"Προβολή λιστών κοντέινερ\"."
 },
 "12 Kurven": {
  "en": "12 curves",
  "fr": "Courbes 12",
  "es": "Curvas 12",
  "pt": "Curvas 12",
  "el": "Καμπύλες 12"
 },
 "20 °C. d20/20 ist relative Dichte; g/mL und kg/m³ sind wahre Dichte. Dieser Rechner addiert keine deutsche Refraktometerkorrektur. Keine Temperaturkorrektur.": {
  "en": "20 °C. d20/20 is relative density; g/mL and kg/m³ are true density. This calculator does not add German refractometer correction. No temperature correction.",
  "fr": "20 °C. d20/20 est la densité relative ; g/mL et kg/m³ sont une véritable densité. Cette calculatrice n'ajoute pas de correction du réfractomètre allemand. Aucune correction de température.",
  "es": "20 °C. d20/20 es densidad relativa; g/mL y kg/m³ son densidad verdadera. Esta calculadora no agrega la corrección del refractómetro alemán. Sin corrección de temperatura.",
  "pt": "20 °C. d20/20 é densidade relativa; g/mL e kg/m³ são densidade verdadeira. Esta calculadora não adiciona correção do refratômetro alemão. Sem correção de temperatura.",
  "el": "20 °C. Το d20/20 είναι σχετική πυκνότητα. Τα g/mL και kg/m³ είναι πραγματική πυκνότητα. Αυτή η αριθμομηχανή δεν προσθέτει γερμανική διόρθωση διαθλασίμετρου. Καμία διόρθωση θερμοκρασίας."
 },
