 "Aktuelle Säure bleibt getrennt von der Anfangssäure der Alkoholprognose. Temperatur angeben, auf die sich die Werte beziehen.": {
  "en": "Current acidity remains separate from the initial acidity of the alcohol forecast. Specify the temperature to which the values refer.",
  "fr": "L'acidité actuelle reste distincte de l'acidité initiale de l'alcool prévu. Précisez la température à laquelle les valeurs se réfèrent.",
  "es": "La acidez actual permanece separada de la acidez inicial del pronóstico de alcohol. Especifique la temperatura a la que se refieren los valores.",
  "pt": "A acidez atual permanece separada da acidez inicial da previsão do álcool. Especifique a temperatura a que os valores se referem.",
  "el": "Η τρέχουσα οξύτητα παραμένει ξεχωριστή από την αρχική οξύτητα της πρόβλεψης αλκοόλ. Καθορίστε τη θερμοκρασία στην οποία αναφέρονται οι τιμές."
 },
