 "Alle Jahrgänge": {
  "en": "All years",
  "fr": "Toutes les années",
  "es": "Todos los años",
  "pt": "Todos os anos",
  "el": "Όλα τα χρόνια"
 },
 "Alle Jahrgänge mit Tanks, Messwerten, Kurven-Grundlagen, Mengenständen, Merkzetteln, bewusst behaltenen Fotos und persönlichen Korrekturen als Datei sichern. Am Saisonende exportieren und die Datei zusätzlich außerhalb dieses Geräts aufbewahren. Die Jahrgänge bleiben weiterhin in der App.": {
  "en": "Save all vintages with tanks, measured values, curve basics, quantity levels, notepads, deliberately retained photos and personal corrections as a file. Export at the end of the season and also keep the file outside of this device. The vintages remain in the app.",
  "fr": "Enregistrez tous les millésimes avec les cuves, les valeurs mesurées, les bases des courbes, les niveaux de quantité, les blocs-notes, les photos délibérément conservées et les corrections personnelles sous forme de fichier. Exportez en fin de saison et conservez également le fichier en dehors de cet appareil. Les millésimes restent dans l'application.",
  "es": "Guarde en un archivo todas las añadas con depósitos, valores medidos, conceptos básicos de curvas, niveles de cantidad, blocs de notas, fotografías conservadas deliberadamente y correcciones personales. Exporte al final de la temporada y también mantenga el archivo fuera de este dispositivo. Las añadas permanecen en la aplicación.",
  "pt": "Salve todas as safras com tanques, valores medidos, curvas básicas, níveis de quantidade, blocos de notas, fotos retidas deliberadamente e correções pessoais em um arquivo. Exporte no final da temporada e também mantenha o arquivo fora deste dispositivo. As safras permanecem no aplicativo.",
  "el": "Αποθηκεύστε όλα τα vintage με δεξαμενές, μετρημένες τιμές, βασικά στοιχεία καμπύλης, επίπεδα ποσότητας, σημειωματάρια, σκόπιμα διατηρημένες φωτογραφίες και προσωπικές διορθώσεις ως αρχείο. Κάντε εξαγωγή στο τέλος της σεζόν και κρατήστε επίσης το αρχείο εκτός αυτής της συσκευής. Οι τρύγοι παραμένουν στην εφαρμογή."
 },
