  "fr": "Les valeurs d'analyse sont affectées à la durée d'échantillonnage ; La date et la source de l'analyse sont dans le tableau. Les valeurs calculées ne sont pas encore disponibles.",
  "es": "Los valores de análisis se asignan al tiempo de muestra; La fecha y la fuente del análisis se encuentran en la tabla. Los valores calculados aún no están disponibles.",
  "pt": "Os valores de análise são atribuídos ao tempo de amostragem; A data e a fonte da análise estão na tabela. Os valores calculados ainda não estão disponíveis.",
  "el": "Οι τιμές ανάλυσης εκχωρούνται στον χρόνο δείγματος. Η ημερομηνία και η πηγή ανάλυσης είναι στον πίνακα. Οι υπολογισμένες τιμές δεν είναι ακόμη διαθέσιμες."
