  "el": "Οι μονάδες σας έχουν αποθηκευτεί. Οι τιμές που έχουν ήδη καταγραφεί και οι εγγραφές που έχουν ήδη ξεκινήσει διατηρούν τις αρχικές τους μονάδες."
