 "Verbesserungen können über Pull Requests vorgeschlagen werden. Die Entscheidung über die Übernahme in die offizielle Version liegt ausschließlich bei Bernhard Schandelmaier und den ausdrücklich benannten berechtigten Projektverantwortlichen.": {
  "en": "Improvements can be suggested via pull requests. The decision about adoption into the official version rests exclusively with Bernhard Schandelmaier and the expressly named authorized project managers.",
  "fr": "Des améliorations peuvent être suggérées via des pull request. La décision concernant l'adoption dans la version officielle appartient exclusivement à Bernhard Schandelmaier et aux chefs de projet autorisés expressément nommés.",
  "es": "Se pueden sugerir mejoras mediante solicitudes de extracción. La decisión sobre la adopción en la versión oficial recae exclusivamente en Bernhard Schandelmaier y los directores de proyecto autorizados expresamente nombrados.",
  "pt": "Melhorias podem ser sugeridas por meio de solicitações pull. A decisão sobre a adoção na versão oficial cabe exclusivamente ao Bernhard Schandelmaier e aos gerentes de projeto autorizados expressamente nomeados.",
  "el": "Μπορούν να προταθούν βελτιώσεις μέσω αιτημάτων έλξης. Η απόφαση σχετικά με την υιοθέτηση στην επίσημη έκδοση ανήκει αποκλειστικά στην Bernhard Schandelmaier και στους ρητά κατονομαζόμενους εξουσιοδοτημένους διαχειριστές έργου."
 },
 "Verbesserungen vorschlagen": {
  "en": "Suggest improvements",
  "fr": "Proposer des améliorations",
  "es": "Sugerir mejoras",
  "pt": "Sugerir melhorias",
  "el": "Προτείνετε βελτιώσεις"
 },
