 "ZXQ4QXZ Proben im Verlauf. ZXQ5QXZ Deshalb wird aus Gärwerten hier kein Alkohol- oder Restzuckergehalt ausgegeben.": {
  "en": "ZXQ4QXZ samples in progress. ZXQ5QXZ That's why no alcohol or residual sugar content is shown here based on fermentation values.",
  "fr": "Échantillons ZXQ4QXZ en cours. ZXQ5QXZ C'est pourquoi aucune teneur en alcool ou en sucre résiduel n'est indiquée ici sur la base des valeurs de fermentation.",
  "es": "Muestras ZXQ4QXZ en progreso. ZXQ5QXZ Es por eso que aquí no se muestra ningún contenido de alcohol o azúcar residual según los valores de fermentación.",
  "pt": "Amostras ZXQ4QXZ em andamento. ZXQ5QXZ É por isso que nenhum teor de álcool ou açúcar residual é mostrado aqui com base nos valores de fermentação.",
  "el": "Δείγματα ZXQ4QXZ σε εξέλιξη. ZXQ5QXZ Γι' αυτό δεν εμφανίζεται εδώ η περιεκτικότητα σε αλκοόλ ή υπολειμματικά σάκχαρα με βάση τις τιμές ζύμωσης."
 },
