 "ZXQ8QXZ Originalwerte. Linien verbinden nur Werte derselben Messspur und Einheit. Durchgezogen: Dichte · gestrichelt: Refraktometer. Keine Restzuckerberechnung aus Gärwerten.": {
  "en": "ZXQ8QXZ Original values. Lines only connect values of the same measurement track and unit. Solid: density · dashed: refractometer. No residual sugar calculation from fermentation values.",
  "fr": "ZXQ8QXZ Valeurs originales. Les lignes relient uniquement les valeurs de la même piste et unité de mesure. Plein : densité · pointillés : réfractomètre. Aucun calcul de sucre résiduel à partir des valeurs de fermentation.",
  "es": "ZXQ8QXZ Valores originales. Las líneas solo conectan valores de la misma pista de medida y unidad. Sólido: densidad · discontinuo: refractómetro. Sin cálculo de azúcar residual a partir de los valores de fermentación.",
  "pt": "ZXQ8QXZ Valores originais. As linhas conectam apenas valores da mesma faixa e unidade de medição. Sólido: densidade · tracejado: refratômetro. Nenhum cálculo de açúcar residual a partir dos valores de fermentação.",
  "el": "ZXQ8QXZ Αρχικές τιμές. Οι γραμμές συνδέουν μόνο τιμές της ίδιας διαδρομής μέτρησης και μονάδας. Στερεό: πυκνότητα · διακεκομμένη: διαθλασίμετρο. Χωρίς υπολογισμό υπολειμμάτων σακχάρου από τις τιμές ζύμωσης."
 },
