 "Übernommene Listen findest du unter „Deine Tanks → Behälterlisten ansehen“.": {
  "en": "You can find adopted lists under “Your tanks → View container lists”.",
  "fr": "Vous pouvez trouver les listes adoptées sous « Vos réservoirs → Afficher les listes de conteneurs ».",
  "es": "Puede encontrar listas adoptadas en “Sus tanques → Ver listas de contenedores”.",
  "pt": "Você pode encontrar listas adotadas em “Seus tanques → Ver listas de contêineres”.",
  "el": "Μπορείτε να βρείτε εγκεκριμένες λίστες στην ενότητα \"Οι δεξαμενές σας → Προβολή λιστών κοντέινερ\"."
 },
 "„ZXQ0QXZ · ZXQ1QXZ“ samt Mengenverlauf, Merkzetteln, Messwerten, Korrekturen und Prognosen wird gelöscht. Vorher bei Bedarf eine Sicherung exportieren.": {
  "en": "“ZXQ0QXZ · ZXQ1QXZ” including the quantity history, notepads, measured values, corrections and forecasts will be deleted. Export a backup beforehand if necessary.",
  "fr": "« ZXQ0QXZ · ZXQ1QXZ » comprenant l'historique des quantités, les blocs-notes, les valeurs mesurées, les corrections et les prévisions seront supprimés. Exportez une sauvegarde au préalable si nécessaire.",
  "es": "Se eliminará “ZXQ0QXZ · ZXQ1QXZ”, incluido el historial de cantidades, blocs de notas, valores medidos, correcciones y pronósticos. Exporte una copia de seguridad de antemano si es necesario.",
  "pt": "“ZXQ0QXZ · ZXQ1QXZ” incluindo o histórico de quantidades, blocos de notas, valores medidos, correções e previsões serão excluídos. Exporte um backup antecipadamente, se necessário.",
  "el": "Το \"ZXQ0QXZ · ZXQ1QXZ\" συμπεριλαμβανομένου του ιστορικού ποσότητας, των σημειώσεων, των τιμών μέτρησης, των διορθώσεων και των προβλέψεων θα διαγραφεί. Εξαγάγετε ένα αντίγραφο ασφαλείας εκ των προτέρων εάν είναι απαραίτητο."
 },
